function topLevelVisualSize(node){const element=document.querySelector(`.flow-node[data-id="${CSS.escape(node.id)}"]`);return{width:element?.offsetWidth||nodeVisualWidth(node),height:element?.offsetHeight||nodeVisualHeight(node)}}
