function zoneBounds(zone){const roots=zoneNodes(zone).filter(node=>!node.parent);if(!roots.length)return null;const boxes=roots.map(node=>{const point=nodeRenderPoint(node),size=topLevelVisualSize(node);return{x:point.x,y:point.y,right:point.x+size.width,bottom:point.y+size.height}}),left=Math.min(...boxes.map(box=>box.x))-38,top=Math.min(...boxes.map(box=>box.y))-118,right=Math.max(...boxes.map(box=>box.right))+38,bottom=Math.max(...boxes.map(box=>box.bottom))+38;return{x:left,y:top,width:Math.max(380,right-left),height:Math.max(270,bottom-top)}}
