async function api(path,options={}){const response=await fetch(path,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options});let data=null;try{data=await response.json()}catch{data=await response.text()}if(!response.ok)throw new Error(data?.error||data?.message||`Ошибка ${response.status}`);return data}
function toast(message,error=false){const el=$("toast");el.textContent=message;el.className=`toast show${error?" error":""}`;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.className="toast",3200)}
function executionFailed(execution){return ["failed","error","cancelled","canceled"].includes(String(execution?.stage||"").toLowerCase())}
function executionFailureDetails(execution){
  if(!executionFailed(execution)&&!execution?.errorInfo)return null;
  const error=execution?.errorInfo||{},raw=String(error.message||"Ошибка выполнения").replace(/\r/g,""),service=raw.match(/https?:\/\/([^/:\s\"]+)/i)?.[1]||null;
  const reason=/Unexpected end of file from server/i.test(raw)?"OCR-сервис оборвал ответ до завершения.":(raw.split("\n").find(Boolean)||"Ошибка выполнения").replace(/\s+/g," ").slice(0,360);
  return {origin:service?`Сервер PowerPlatform · ${service}`:"Сервер PowerPlatform",node:error.function||"не указан",reason};
}
function executionResultText(execution,logs=[]){
  const code=execution?.code||execution?.id||"процесса",failure=executionFailureDetails(execution);
  if(failure)return `Выполнение ${code}: ОШИБКА\n\nРезультат не создан.\nИсточник: ${failure.origin}\nНод: ${failure.node}\nПричина: ${failure.reason}`;
  const answer=logs.length?logs[logs.length-1]?.info:null,stage=String(execution?.stage||"").toLowerCase()||"запущено";
  return `Выполнение ${code}: ${stage}.${answer?`\n\nРезультат:\n${answer}`:""}`;
}
function executionStateFrom(value,fallback="done"){const text=String(value||"").toLowerCase();if(/fail|error|exception|cancel|ошиб/.test(text))return"error";if(/run|start|progress|active|execut|выполн/.test(text))return"active";if(/finish|complete|success|done|pass|готов|заверш/.test(text))return"done";return fallback}
function executionSignals(value,result=[],depth=0,seen=new Set()){if(value==null||depth>6||result.length>600)return result;if(typeof value!=="object")return result;if(seen.has(value))return result;seen.add(value);if(Array.isArray(value)){value.forEach(item=>executionSignals(item,result,depth+1,seen));return result}const candidate=value.nodeId??value.nodeID??value.functionId??value.function??value.nodeCode??value.nodeName??(typeof value.node==="string"?value.node:null);if(candidate!=null)result.push({candidate:String(candidate),state:executionStateFrom(value.status??value.stage??value.state??value.event??value.type,depth?"done":"active")});Object.values(value).forEach(item=>executionSignals(item,result,depth+1,seen));return result}
function findExecutionNode(candidate){const key=String(candidate||"").trim().toLocaleLowerCase("ru");if(!key)return null;const zoneId=state.executionVisual.zoneId,candidates=zoneId?state.nodes.filter(node=>node.zoneId===zoneId):state.nodes;return candidates.find(node=>[node.id,node.platformNodeId,node.functionId,node.sourceRef,node.title].filter(Boolean).some(value=>String(value).trim().toLocaleLowerCase("ru")===key))||candidates.find(node=>String(node.title||"").toLocaleLowerCase("ru").includes(key)||(node.functionId&&key.includes(String(node.functionId).toLocaleLowerCase("ru"))))}
function clearExecutionTransferTimers(visual=state.executionVisual){visual?.transferTimers?.forEach(timer=>clearTimeout(timer));visual?.transferTimers?.clear();if(visual?.eventTimer)clearTimeout(visual.eventTimer);if(visual){visual.eventTimer=null;visual.eventQueue=[];visual.pendingTerminal=null}}
function executionRoots(zoneId=state.executionVisual.zoneId){const processIds=new Set(state.nodes.filter(node=>node.kind==="process"&&(!zoneId||node.zoneId===zoneId)).map(node=>node.id)),incoming=new Set(state.edges.filter(edge=>processIds.has(edge.from.node)&&processIds.has(edge.to.node)).map(edge=>edge.to.node));return state.nodes.filter(node=>processIds.has(node.id)&&!incoming.has(node.id))}
function visualNodeIds(nodeId){const top=topLevelNodeId(nodeId);return top&&top!==nodeId?[nodeId,top]:[nodeId]}
function setExecutionNodeState(nodeId,value){visualNodeIds(nodeId).forEach(id=>state.executionVisual.nodeStates.set(id,value))}
function paintExecutionVisual(){document.querySelectorAll(".flow-node").forEach(element=>{const value=state.executionVisual.nodeStates.get(element.dataset.id);["active","waiting","done","error"].forEach(name=>element.classList.toggle(`exec-${name}`,value===name))});$("viewport").classList.toggle("execution-running",state.executionVisual.active);renderEdges();if(state.groupView)renderGroupWires(state.groupView.nodes,state.groupView.layout)}
function beginExecutionVisual(executionId,modelId){clearExecutionTransferTimers();const zone=state.zones.find(item=>item.kind==="process"&&String(item.sourceId)===String(modelId)),graphMatched=Boolean(zone),nodeStates=new Map();state.executionVisual={active:true,executionId:String(executionId||""),graphMatched,zoneId:zone?.id||null,nodeStates,edgeStates:new Map(),seenNodeIds:new Set(),telemetry:false,lastSeq:0,lastNodeId:null,observerConnected:false,transferTimers:new Map(),eventQueue:[],eventTimer:null,pendingTerminal:null};if(graphMatched)executionRoots(zone.id).forEach(node=>nodeStates.set(node.id,"active"));paintExecutionVisual();$("interaction-hint").textContent=graphMatched?`Запуск принят · рамка №${zone.number}`:"Запуск принят · модель запуска не размещена на поле"}
function markExecutionUpstreamDone(nodeId,visited=new Set()){if(visited.has(nodeId))return;visited.add(nodeId);state.edges.filter(edge=>edge.to.node===nodeId).forEach(edge=>{state.executionVisual.edgeStates.set(edge.id,"done");const source=state.nodes.find(node=>node.id===edge.from.node);if(source&&state.executionVisual.nodeStates.get(source.id)!=="error"){setExecutionNodeState(source.id,"done");markExecutionUpstreamDone(source.id,visited)}})}
function beginExecutionTransfer(edge){const visual=state.executionVisual,previousTimer=visual.transferTimers.get(edge.id);if(previousTimer)clearTimeout(previousTimer);visual.edgeStates.set(edge.id,"transfer");const target=state.nodes.find(node=>node.id===edge.to.node);if(target&&!['done','error'].includes(visual.nodeStates.get(target.id)))setExecutionNodeState(target.id,"active");const timer=setTimeout(()=>{if(state.executionVisual!==visual)return;if(visual.edgeStates.get(edge.id)==="transfer")visual.edgeStates.set(edge.id,"done");visual.transferTimers.delete(edge.id);paintExecutionVisual()},1150);visual.transferTimers.set(edge.id,timer)}
function applyNodeExecution(nodeId,success=true){const node=findExecutionNode(nodeId);if(!node)return false;const visual=state.executionVisual,previous=visual.nodeStates.get(node.id);visual.seenNodeIds.add(node.id);if(previous==="done"&&success!==false||previous==="error"&&success===false)return true;visual.telemetry=true;markExecutionUpstreamDone(node.id);state.edges.filter(edge=>edge.to.node===node.id).forEach(edge=>{const timer=visual.transferTimers.get(edge.id);if(timer)clearTimeout(timer);visual.transferTimers.delete(edge.id);visual.edgeStates.set(edge.id,"done")});if(success===false){setExecutionNodeState(node.id,"error");state.edges.filter(edge=>edge.from.node===node.id).forEach(edge=>visual.edgeStates.delete(edge.id));return true}setExecutionNodeState(node.id,"done");state.edges.filter(edge=>edge.from.node===node.id).forEach(beginExecutionTransfer);return true}
function applyDebugPosition(nodeId){const node=findExecutionNode(nodeId);if(!node)return false;const visual=state.executionVisual,previous=visual.lastNodeId?state.nodes.find(item=>item.id===visual.lastNodeId):null;visual.telemetry=true;if(previous&&previous.id!==node.id)setExecutionNodeState(previous.id,"done");state.edges.filter(edge=>edge.to.node===node.id&&visual.seenNodeIds.has(edge.from.node)).forEach(beginExecutionTransfer);if(visual.nodeStates.get(node.id)!=="error")setExecutionNodeState(node.id,"active");visual.seenNodeIds.add(node.id);visual.lastNodeId=node.id;return true}
function finishExecutionVisual(failed=false){const visual=state.executionVisual;if(!failed&&visual.telemetry){clearExecutionTransferTimers(visual);visual.nodeStates.forEach((value,id)=>{if(value==="active"||value==="waiting")visual.nodeStates.set(id,"done")});state.edges.forEach(edge=>{if(visual.seenNodeIds.has(edge.from.node)&&visual.seenNodeIds.has(edge.to.node))visual.edgeStates.set(edge.id,"done")})}else if(!visual.telemetry){clearExecutionTransferTimers(visual);visual.nodeStates.clear();visual.edgeStates.clear()}visual.active=false;visual.pendingTerminal=null;paintExecutionVisual();$("interaction-hint").textContent=failed?"Выполнение остановилось с ошибкой":"Выполнение завершено"}
function applyTraceEvent(event){const name=String(event?.event||"").toUpperCase();if(name==="NODE_EXECUTION"&&event.nodeId!=null)applyNodeExecution(event.nodeId,event.success!==false);else if(name==="DEBUG_POSITION_CHANGED"&&event.nodeId!=null)applyDebugPosition(event.nodeId)}
function pumpExecutionTrace(){const visual=state.executionVisual;if(visual.eventTimer)return;if(!visual.eventQueue.length){if(visual.pendingTerminal)finishExecutionVisual(visual.pendingTerminal.failed);return}applyTraceEvent(visual.eventQueue.shift());paintExecutionVisual();const delay=visual.eventQueue.length>20?80:visual.eventQueue.length>8?140:360;visual.eventTimer=setTimeout(()=>{if(state.executionVisual!==visual)return;visual.eventTimer=null;pumpExecutionTrace()},delay)}
function applyTraceSnapshot(snapshot){const visual=state.executionVisual;if(!snapshot||String(snapshot.executionId||"")!==visual.executionId)return;visual.observerConnected=Boolean(snapshot.connected);visual.lastSeq=Math.max(visual.lastSeq,Number(snapshot.lastSeq||0));const events=array(snapshot.events).sort((a,b)=>Number(a.seq||0)-Number(b.seq||0)).filter(event=>["NODE_EXECUTION","DEBUG_POSITION_CHANGED"].includes(String(event.event||"").toUpperCase())&&event.nodeId!=null);if(events.length){visual.telemetry=true;visual.eventQueue.push(...events);pumpExecutionTrace()}if(snapshot.nodeTelemetry)visual.telemetry=true}
function restoreExecutionTrace(executionId,modelId,snapshot,failed=false){beginExecutionVisual(executionId,modelId);const visual=state.executionVisual;if(!snapshot||String(snapshot.executionId||"")!==visual.executionId){finishExecutionVisual(failed);return}visual.observerConnected=Boolean(snapshot.connected);visual.lastSeq=Number(snapshot.lastSeq||0);array(snapshot.events).sort((a,b)=>Number(a.seq||0)-Number(b.seq||0)).filter(event=>["NODE_EXECUTION","DEBUG_POSITION_CHANGED"].includes(String(event.event||"").toUpperCase())&&event.nodeId!=null).forEach(applyTraceEvent);if(snapshot.nodeTelemetry)visual.telemetry=true;finishExecutionVisual(failed)}
function applyExecutionVisual(details,trace=null){const execution=details.execution||{},stage=String(execution.stage||"").toLowerCase(),terminal=["finished","failed","error","cancelled","canceled"].includes(stage),failed=executionFailed(execution);applyTraceSnapshot(trace);executionSignals(details.details).forEach(signal=>{const node=findExecutionNode(signal.candidate);if(!node)return;state.executionVisual.telemetry=true;if(signal.state==="done")applyNodeExecution(node.id,true);else if(signal.state==="error")applyNodeExecution(node.id,false);else setExecutionNodeState(node.id,"active")});const failure=executionFailureDetails(execution),failedNode=findExecutionNode(failure?.node);if(failedNode){state.executionVisual.telemetry=true;applyNodeExecution(failedNode.id,false)}const visual=state.executionVisual,pending=visual.eventQueue.length||visual.eventTimer;if(terminal&&pending)visual.pendingTerminal={failed};else if(terminal)finishExecutionVisual(failed);else visual.active=true;paintExecutionVisual();const completed=[...visual.nodeStates.values()].filter(value=>value==="done").length;if(terminal&&pending)$("interaction-hint").textContent=`Процесс завершён · показываю последние события (${visual.eventQueue.length})`;else if(!terminal)$("interaction-hint").textContent=visual.telemetry?`Выполнение · подтверждено нодов: ${completed}`:visual.observerConnected?"Наблюдатель подключён · жду событие ноды":"Процесс выполняется · подключаю наблюдатель"}
function platformProvenance(){return {owner:"platform",label:"Платформа",deployment:"READY",requirement:null}}
function projectProvenance(requirement="Требуется добавить или зарегистрировать компонент на платформе"){return {owner:"project",label:"Наше",deployment:"BLOCKED",requirement}}
function isOntologyDefinition(definition){return String(definition?.group||"").trim()==="Фабрика онтологии домена"||String(definition?.id||definition?.function||"").startsWith("dof-dof-")}
function isOntologyNode(node){return node?.kind==="ontology"||isOntologyDefinition({group:node?.definition?.group||node?.group,id:node?.sourceRef||node?.functionId})}
function provenanceOf(node){
  if(node?.provenance?.owner)return node.provenance;
  if(node?.kind==="cadlib")return projectProvenance("Требуется платформенная интеграция CADLib и её опубликованная нода");
  if(node?.definition?.deployment){const deployment=node.definition.deployment,status=String(deployment.status||"LOCAL_ONLY").toUpperCase();return {owner:"project",label:"Наше",deployment:status==="READY"?"READY":"BLOCKED",requirement:deployment.pasAdapter?null:"Требуется PAS-адаптер и регистрация ноды"}}
  return platformProvenance();
}
function deploymentOf(node){
  const provenance=provenanceOf(node),project=provenance.owner==="project",ready=provenance.deployment==="READY";
  return {node,provenance,state:ready?"ready":"blocked",title:ready?(project?"Наш компонент зарегистрирован":"Нативная нода платформы"):(provenance.requirement||"Компонент пока доступен только локально")};
}
