function remember(){state.history.push(JSON.stringify({nodes:state.nodes,edges:state.edges,zones:state.zones,activeZoneId:state.activeZoneId,nextZoneNumber:state.nextZoneNumber}));if(state.history.length>30)state.history.shift();$("undo").disabled=false}
function undo(){const raw=state.history.pop();if(!raw)return;const snapshot=JSON.parse(raw);state.nodes=snapshot.nodes;state.edges=snapshot.edges;state.zones=snapshot.zones||state.zones;state.activeZoneId=snapshot.activeZoneId||state.activeZoneId;state.nextZoneNumber=snapshot.nextZoneNumber||state.nextZoneNumber;state.selectedId=null;state.selectedEdgeId=null;state.selectedIds.clear();activateZone(state.activeZoneId,false);renderAll();markChanged();$("undo").disabled=!state.history.length}

