function setSelection(ids=[],primary=null){state.selectedIds=new Set(ids);state.selectedId=primary&&state.selectedIds.has(primary)?primary:(ids.at(-1)||null);state.selectedEdgeId=null;state.menuNode=null;renderSelection();renderInspector()}
