  const head=el.querySelector(".node-head");head.addEventListener("pointerdown",event=>{if(event.button!==0||event.target.closest("button"))return;event.preventDefault();event.stopPropagation();selectNode(node.id,event,true);if(!state.selectedIds.has(node.id)){state.selectedIds.add(node.id);state.selectedId=node.id;renderSelection();renderInspector()}const start=screenToWorld(event.clientX,event.clientY),movingIds=selectionIds(),origins=new Map(movingIds.map(id=>{const item=state.nodes.find(candidate=>candidate.id===id);return [id,{x:item.x,y:item.y}]}));let moved=false;head.setPointerCapture(event.pointerId);const move=e=>{const point=screenToWorld(e.clientX,e.clientY);if(!moved&&Math.hypot(point.x-start.x,point.y-start.y)>2){remember();moved=true}if(!moved)return;origins.forEach((origin,id)=>{const item=state.nodes.find(candidate=>candidate.id===id);item.x=Math.round(origin.x+point.x-start.x);item.y=Math.round(origin.y+point.y-start.y)});syncRenderedPositions();renderEdges();renderMinimap()};const up=()=>{head.removeEventListener("pointermove",move);head.removeEventListener("pointerup",up);if(moved)markChanged()};head.addEventListener("pointermove",move);head.addEventListener("pointerup",up)});
