function beginCanvasPan(viewport,event){event.preventDefault();const origin={x:event.clientX,y:event.clientY,panX:state.pan.x,panY:state.pan.y};viewport.classList.add("panning");viewport.setPointerCapture(event.pointerId);const move=e=>{state.pan.x=origin.panX+e.clientX-origin.x;state.pan.y=origin.panY+e.clientY-origin.y;applyTransform();requestAnimationFrame(renderEdges)};const up=()=>{viewport.classList.remove("panning");viewport.removeEventListener("pointermove",move);viewport.removeEventListener("pointerup",up);viewport.removeEventListener("pointercancel",up);schedulePersist()};viewport.addEventListener("pointermove",move);viewport.addEventListener("pointerup",up);viewport.addEventListener("pointercancel",up)}

function screenToWorld(clientX,clientY){const rect=$("viewport").getBoundingClientRect();return {x:(clientX-rect.left-state.pan.x)/state.zoom,y:(clientY-rect.top-state.pan.y)/state.zoom}}
