function compactUnusedPorts(){state.portView="used";renderAll();fitGraph();schedulePersist();toast("Вписано: неиспользуемые порты скрыты")}
function expandAllPorts(){state.portView="all";if(state.nodes.length)autoLayout(true,false);else renderAll();schedulePersist();toast("Разложено: все входы и выходы показаны")}

function autoLayout(record=false,notify=true){
  if(!state.nodes.length)return;
  if(record)remember();
  const zones=state.zones.filter(zone=>zoneNodes(zone).some(node=>!node.parent));
  zones.forEach(zone=>layoutZone(zone));
  const unzoned=state.nodes.filter(node=>!node.parent&&!node.zoneId);
  if(unzoned.length){const columns=Math.max(1,Math.ceil(Math.sqrt(unzoned.length))),cellHeight=Math.max(190,...unzoned.map(node=>nodeVisualHeight(node)+55));unzoned.slice().sort((a,b)=>a.title.localeCompare(b.title,"ru")).forEach((node,index)=>{node.x=90+(index%columns)*360;node.y=95+Math.floor(index/columns)*cellHeight})}
  renderAll();fitGraph();schedulePersist();if(notify)toast(`Ноды разложены внутри рамок: ${zones.length}`)
}

async function loadCatalog(){state.catalogPage=0;try{const data=await api("/api/local/pas/nodes?limit=2500");state.catalog=array(data);state.catalogTotal=Number(data.total||state.catalog.length);renderCatalog()}catch(error){$("node-list").innerHTML=`<div class="loading-row">${esc(error.message)}</div>`;toast("Библиотека нодов недоступна",true)}}
function catalogMatches(item,query){const normalized=query.trim().toLocaleLowerCase("ru");return !normalized||`${item.name||""} ${item.id||""} ${item.group||""}`.toLocaleLowerCase("ru").includes(normalized)}
function catalogItem(item,index,search=false){const ontology=isOntologyDefinition(item);return `<button class="catalog-item${search?" search-result":""}${ontology?" ontology-item":""}" draggable="true" data-index="${index}"><span class="catalog-icon">${ontology?"◈":"ƒ"}</span><span><strong>${esc(item.name||item.id)}</strong>${search?`<small>${esc(item.group||"")}</small>`:`<small>${item.inputs?.length||0} входов · ${item.outputs?.length||0} выходов</small>`}</span><span class="catalog-add">＋</span></button>`}
function bindCatalogItems(rootId="node-list"){$(rootId).querySelectorAll(".catalog-item").forEach(button=>{const def=state.catalog[Number(button.dataset.index)];button.onclick=()=>addCatalogNode(def);button.ondragstart=event=>{event.dataTransfer.setData("application/x-power-node",JSON.stringify({kind:"process",index:Number(button.dataset.index)}));event.dataTransfer.effectAllowed="copy"}})}
function renderCatalog(){const allEntries=state.catalog.map((item,index)=>({item,index})),entries=allEntries.filter(({item})=>catalogMatches(item,state.catalogQuery)),query=state.catalogQuery.trim(),pager=document.querySelector("#process-library .pager");$("node-total").textContent=allEntries.length.toLocaleString("ru-RU");if(query){const pages=Math.max(1,Math.ceil(entries.length/PAGE_SIZE));state.catalogPage=Math.min(state.catalogPage,pages-1);const start=state.catalogPage*PAGE_SIZE,page=entries.slice(start,start+PAGE_SIZE);pager.hidden=false;$("nodes-page").textContent=`${state.catalogPage+1} / ${pages}`;$("nodes-prev").disabled=state.catalogPage<=0;$("nodes-next").disabled=state.catalogPage>=pages-1;$("node-list").innerHTML=page.map(({item,index})=>catalogItem(item,index,true)).join("")||'<div class="loading-row">Ничего не найдено</div>'}
  else{pager.hidden=true;const grouped=new Map();entries.forEach(({item,index})=>{const title=item.group||"Без группы";if(!grouped.has(title))grouped.set(title,[]);grouped.get(title).push({item,index})});const groups=[...grouped.entries()].sort((a,b)=>a[0].localeCompare(b[0],"ru"));$("node-list").innerHTML=groups.map(([title,items],groupIndex)=>{const open=state.openNodeGroups.has(title);return `<section class="node-group${open?" open":""}" data-group-index="${groupIndex}"><button class="node-group-button"><span>›</span><strong>${esc(title)}</strong><b>${items.length}</b></button><div class="node-group-items">${open?items.map(({item,index})=>catalogItem(item,index)).join(""):""}</div></section>`}).join("")||'<div class="loading-row">Ноды не найдены</div>';$("node-list").querySelectorAll(".node-group").forEach(section=>{const title=groups[Number(section.dataset.groupIndex)][0];section.querySelector(".node-group-button").onclick=()=>{state.openNodeGroups.has(title)?state.openNodeGroups.delete(title):state.openNodeGroups.add(title);renderCatalog()}})}bindCatalogItems()}

function ontologyModel(ontology){return ontology?.model||{}}
function ontologyContents(ontology){const model=ontologyModel(ontology);return{types:array(model.types),connections:array(model.connections)}}
function ontologyMatches(ontology,query){const normalized=query.trim().toLocaleLowerCase("ru");if(!normalized)return true;const{types,connections}=ontologyContents(ontology);const searchable=[ontology.title,ontology.code,ontology.description,...types.flatMap(type=>[type.name,type.description,...array(type.attributes).flatMap(attribute=>[attribute.name,attribute.type])]),...connections.flatMap(connection=>[connection.name,connection.from,connection.to,connection.cardinality])].filter(Boolean).join(" ").toLocaleLowerCase("ru");return searchable.includes(normalized)}
