function ontologyConnectionHtml(connection){return `<div class="ontology-connection"><span>${esc(connection.from||"?")} <b>→</b> ${esc(connection.to||"?")}</span><small>${esc(connection.name||"Связь")} · ${esc(connection.cardinality||"кардинальность не указана")}</small></div>`}
function ontologyDetailsHtml(ontology){const{types,connections}=ontologyContents(ontology);return `<div class="ontology-details">${ontology.description?`<p>${esc(ontology.description)}</p>`:""}<button type="button" class="ontology-to-canvas" data-ontology-diagram="${esc(ontology.id)}">◈ Вывести диаграмму на поле</button><div class="ontology-section-title"><span>Типы</span></div>${types.map(ontologyTypeHtml).join("")||'<div class="ontology-empty">Типы не определены</div>'}<div class="ontology-section-title"><span>Связи</span></div>${connections.map(ontologyConnectionHtml).join("")||'<div class="ontology-empty">Связей нет</div>'}</div>`}
async function loadOntologies(){try{state.ontologies=array(await api("/api/local/dof/ontologies"));renderOntologyCatalog()}catch(error){$("ontology-list").innerHTML=`<div class="loading-row">${esc(error.message)}</div>`;$("ontology-total").textContent="0";$("ontology-summary").textContent="Фабрика онтологий недоступна";toast("Фабрика онтологий недоступна",true)}}
async function toggleOntology(id){if(state.ontologyId===id){state.ontologyId=null;renderOntologyCatalog();return}state.ontologyId=id;renderOntologyCatalog();try{const detail=await api(`/api/local/dof/ontologies/${encodeURIComponent(id)}`),index=state.ontologies.findIndex(item=>String(item.id)===String(id));if(index>=0)state.ontologies[index]=detail;renderOntologyCatalog()}catch(error){toast(`Не удалось прочитать онтологию: ${error.message}`,true)}}
function ontologyGraphNode(type,index,zoneId){return{id:`ontology-type-${index}-${uid("t")}`,kind:"ontology",zoneId,title:type.name||`Тип ${index+1}`,description:type.description||"Тип данных онтологии",x:0,y:0,inputs:[],outputs:[],attributes:structuredClone(array(type.attributes)),ontologyIndex:index,originalName:type.name||"",sourceRef:type.systemName||type.name||null,provenance:platformProvenance()}}
