function controlSuppliesPort(node,portName){const controls=node.controls;if(!controls||Array.isArray(controls)||typeof controls!=="object"||!Object.prototype.hasOwnProperty.call(controls,portName))return false;const value=controls[portName];return value!==null&&value!==undefined&&value!==""}
