function codexCatalogHints(message){const stop=new Set(["добавь","добавить","ноду","ноды","схему","схеме","соедини","связать","потом","между","через","чтобы","нужно","сделай","удали","перемести","группу","группе","выход","вход"]),words=String(message||"").toLocaleLowerCase("ru").split(/[^\p{L}\p{N}_-]+/u).filter(word=>word.length>=3&&!stop.has(word));return state.catalog.map(item=>{const id=String(item.id||"").toLocaleLowerCase("ru"),name=String(item.name||"").toLocaleLowerCase("ru"),text=`${id} ${name} ${item.group||""}`.toLocaleLowerCase("ru");let score=0;words.forEach(word=>{if(id===word||name===word)score+=8;else if(id.includes(word)||name.includes(word))score+=4;else if(text.includes(word))score+=1});return{item,score}}).filter(row=>row.score>0).sort((a,b)=>b.score-a.score||String(a.item.name).localeCompare(String(b.item.name),"ru")).slice(0,100).map(({item})=>({id:item.id,name:item.name,group:item.group,inputs:normalizeInputs(item.inputs).map(port=>({name:port.name,title:port.title,type:port.type})),outputs:normalizeOutputs(item.outputs).map(port=>({name:port.name,title:port.title,type:port.type}))}))}
