function codexPlanNodeName(value,plan=null){const node=state.nodes.find(item=>item.id===value);if(node)return node.title;const action=(plan||state.codex.pendingPlan?.plan)?.actions?.find(item=>item.type==="add_node"&&item.ref===value),definition=action&&state.catalog.find(item=>item.id===action.functionId);return definition?.name||action?.functionId||value||"?"}
function codexActionText(action,plan=null){if(action.type==="add_node")return`Добавить «${state.catalog.find(item=>item.id===action.functionId)?.name||action.functionId}»`;if(action.type==="remove_node")return`Убрать «${codexPlanNodeName(action.nodeId,plan)}»`;if(action.type==="move_node")return`Переместить «${codexPlanNodeName(action.nodeId,plan)}»`;if(action.type==="rename_node")return`Переименовать «${codexPlanNodeName(action.nodeId,plan)}» → «${action.title}»`;if(action.type==="connect")return`Связать ${codexPlanNodeName(action.fromNode,plan)}.${action.fromPort} → ${codexPlanNodeName(action.toNode,plan)}.${action.toPort}`;if(action.type==="disconnect")return`Удалить связь ${action.edgeId}`;if(action.type==="group_nodes")return`Собрать ${action.nodeIds?.length||0} нодов в «${codexPlanNodeName(action.groupNodeId,plan)}»`;if(action.type==="ungroup_nodes")return`Извлечь из группы: ${action.nodeIds?.length||0}`;if(action.type==="layout")return"Разложить плашки без наложений";return action.type}
