function paintCodexPreviewMarks(){document.querySelectorAll(".flow-node").forEach(element=>element.classList.remove("codex-preview-change","codex-preview-remove"));document.querySelectorAll(".wire-group").forEach(element=>element.classList.remove("codex-preview-change","codex-preview-remove"));const pending=state.codex.pendingPlan;if(!pending)return;const markNode=(id,remove=false)=>{if(!id)return;const element=document.querySelector(`.flow-node[data-id="${CSS.escape(id)}"]`);if(element)element.classList.add(remove?"codex-preview-remove":"codex-preview-change")};pending.plan.actions.forEach(action=>{if(action.type==="remove_node")markNode(action.nodeId,true);if(["move_node","rename_node"].includes(action.type))markNode(action.nodeId);if(action.type==="connect"){markNode(action.fromNode);markNode(action.toNode)}if(action.type==="disconnect"){const edge=document.querySelector(`.wire-group[data-edge="${CSS.escape(action.edgeId||"")}"]`);if(edge)edge.classList.add("codex-preview-remove")}if(action.type==="group_nodes"){markNode(action.groupNodeId);array(action.nodeIds).forEach(id=>markNode(id))}if(action.type==="ungroup_nodes")array(action.nodeIds).forEach(id=>markNode(id))})}
